                },
                "is_admin": {
                  "type": "integer",
                  "minimum": 0,
                  "description": "0/1 în profilul contului web; Bearer nu acordă administrarea platformei."
                },
                "email_verified": {
                  "type": "integer",
                  "minimum": 0,
                  "description": "0/1 în profilul contului web; Bearer nu acordă administrarea platformei."
                }
              },
